namespace SmartRail.Domain.Journeys;

public enum EventType
{
    Departed, Arrived, DelayReported, ReasonVerified, OverrideSet, OverrideCleared, PlatformChanged, ReportFlagged
}

public enum EventSource { Operator, Controller, Simulator }

/// <summary>An entry in the append-only audit trail (D-36). The database refuses UPDATE and DELETE.</summary>
public sealed class TrainEvent
{
    public Guid Id { get; set; }
    public Guid JourneyId { get; set; }

    /// <summary>Generated by the client per tap and kept through retries (D-35); unique per journey.</summary>
    public Guid ClientEventId { get; set; }

    public EventType EventType { get; set; }
    public Guid? ServiceStopId { get; set; }
    public DateTimeOffset OccurredAt { get; set; }
    public DateTimeOffset ReceivedAt { get; set; }
    public EventSource Source { get; set; }

    /// <summary>The Keycloak subject of whoever created the event.</summary>
    public required string CreatedBy { get; set; }

    /// <summary>Event-specific data as JSON text, stored as jsonb.</summary>
    public string? Payload { get; set; }

    public int JourneyVersionAfter { get; set; }
}
